        try:
            src_dist = {d: nx.dijkstra_path_length(W, src, d) for d in reachable}
        except nx.NetworkXException:
            src_dist = {d: inf for d in reachable}
        # R=10 deterministic orderings (no more starts than the parent ran).
        orders = [
            sorted(reachable, key=str),
            sorted(reachable, key=lambda d: (src_dist.get(d, inf), str(d))),
        ]
        for r in range(8):
            salt = r + 1

            def hkey(d, _s=salt):
                hv = 2166136261
                for ch in str(d) + "|" + str(_s):
                    hv = ((hv ^ ord(ch)) * 16777619) & 0xFFFFFFFF
                return (hv % 1000003, str(d))

            orders.append(sorted(reachable, key=hkey))
        for order in orders:
            edges = sph(order)
            if edges is None:
                continue
            r_routes = routes_from_edges(edges)
            if r_routes is None:
                continue
            c = sp_cost(list(r_routes.values()))
            if c < tree_cost:
                tree_cost = c
                tree_routes = r_routes

